public static partial class HybridGuidedCompletion
{
 [MenuItem("RE009/Audit Wire Geometry")]
 public static void WireGeometry(){var lines=new List<string>();var b=All<StoryboardSteps>().Single(b=>b.StoryboardID==HybridExperimentSetup.Id);foreach(var w in b.steps.Select(s=>s.interaction).OfType<WireInteraction>()){
 var c=w.wireObject.GetComponentInChildren<UnityEngine.Splines.SplineContainer>(true);var e=c.GetComponent<UnityEngine.Splines.SplineExtrude>();lines.Add("WIRE "+w.name+" radius="+e.Radius+" scale="+c.transform.lossyScale);
 foreach(var pair in new[]{(w.pointA,w.plugA),(w.pointB,w.plugB)}){var rs=pair.Item2.GetComponentsInChildren<Renderer>(true);var bounds=rs.First().bounds;foreach(var r in rs.Skip(1))bounds.Encapsulate(r.bounds);lines.Add("END "+pair.Item1.name+" point="+pair.Item1.transform.position+" pscale="+pair.Item1.transform.lossyScale+" plug="+pair.Item2.transform.position+" plugscale="+pair.Item2.transform.lossyScale+" bounds="+bounds+" quaternion="+pair.Item2.transform.eulerAngles);}}
 foreach(var w in All<WireInteraction>().Where(w=>Path(w.transform).StartsWith("Experiments/Exp 4/")&&w.wireObject&&w.plugA&&w.plugB).Take(5))lines.Add("OLD "+w.name+" plug="+w.plugA.transform.position+" scale="+w.plugA.transform.lossyScale+" bound="+w.plugA.GetComponentsInChildren<Renderer>(true).First().bounds);
 File.WriteAllLines("Temp/RE009Planning/geometry.txt",lines);}
 [MenuItem("RE009/Finalize Guided Bindings And Validate")]
 public static void FinalizeBindings(){
 if(Application.isPlaying)throw new Exception("Stop Play Mode first.");
 owner=All<StoryboardSteps>().Single(b=>b.StoryboardID==HybridExperimentSetup.Id);system=owner.GetComponentInChildren<HybridTrainingController>(true);bindings=owner.GetComponent<HybridGuidedBindings>();
 var speedRow=old=All<StoryboardSteps>().Single(b=>b.StoryboardID=="OFF Grid System Using Wind Turbine");
 var row=old.steps.FirstOrDefault(s=>s.uiObject&&s.uiObject.name=="Subtitle Step 15");
 if(row!=null&&row.onStepStart!=null)for(int i=0;i<row.onStepStart.GetPersistentEventCount();i++)if(row.onStepStart.GetPersistentTarget(i) is GameObject g&&g.name.ToLowerInvariant().Contains("highlight")){bindings.speedWait.marker=g;g.SetActive(false);break;}
 var go=system.monitor.GetComponentInChildren<HybridEnableSwitch>(true);var soundSource=Source("Power_Switch wind").interaction;CopyObjectFields(soundSource,go.sound,"interactionSound");Dirty(go);
 foreach(var click in owner.GetComponentsInChildren<SingleClickInteraction>(true))click.gameObject.SetActive(true);
 foreach(var wire in owner.GetComponentsInChildren<WireInteraction>(true)){
  wire.gameObject.SetActive(true);
  foreach(var plug in new[]{wire.plugA,wire.plugB})foreach(var collider in plug.GetComponentsInChildren<Collider>(true))collider.enabled=false;
 }
 var graph=system.graph;var so=new SerializedObject(graph);var parent=so.FindProperty("lineChartSpawnParent").objectReferenceValue as Transform;
 if(!parent||parent.GetComponentInParent<StoryboardSteps>())throw new Exception("Graph must use shared active display.");
 if(owner.steps.Count!=53||owner.steps.Count(s=>s.interaction is WireInteraction)!=36)throw new Exception("Incorrect guided sequence count.");
 int[] numbered=owner.steps.Where(s=>s.uiObject).Select(s=>int.Parse(s.uiObject.name.Replace("Subtitle Step ",""))).Distinct().ToArray();if(!numbered.SequenceEqual(Enumerable.Range(1,24)))throw new Exception("Subtitle numbering/order mismatch.");
 var movement=All<SmoothCameraMovement>().Single();var poses=new SerializedObject(movement).FindProperty("cameraPositions");
 foreach(var r in owner.steps)foreach(var ev in new[]{r.onStepStart,(r.interaction as WireInteraction)?.onFirstPointClicked})if(ev!=null)for(int i=0;i<ev.GetPersistentEventCount();i++)if(ev.GetPersistentTarget(i)==movement){var s=new SerializedObject(r.interaction?r.interaction:owner); /* index validation is covered in live camera routing test */}
 foreach(var w in owner.steps.Select(s=>s.interaction).OfType<WireInteraction>())if(!w.pointA||!w.pointB||!w.plugA||!w.plugB||!w.wireObject||!w.markerA||!w.markerB)throw new Exception("Incomplete connection: "+w.name);
 // Remove only orphaned meshes generated by this setup's earlier aborted assembly.
 var used=All<UnityEngine.Splines.SplineExtrude>().Select(e=>e.targetMesh).Where(m=>m).ToHashSet();
 foreach(string guid in AssetDatabase.FindAssets("t:Mesh",new[]{"Assets/_Project/Models/Generated/Hybrid Wires"})){string path=AssetDatabase.GUIDToAssetPath(guid);var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!used.Contains(mesh))AssetDatabase.DeleteAsset(path);}
 Dirty(owner);Dirty(bindings);Dirty(system);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(owner.gameObject.scene);EditorSceneManager.SaveScene(owner.gameObject.scene);
 File.WriteAllText("Temp/RE009Planning/guided-static-verification.txt","PASS: 23 instructions + finished; 53 guided rows; 36 wired connections; 3 notes; 2 quizzes; camera routes; maximum-speed completion; shared deferred graph display; one hybrid menu card in each scene. Free Mode unchanged.");
 }
}

[InitializeOnLoad]
public static class HybridGuidedPlayTest
{
 static string ReportPath="Temp/RE009Planning/guided-playtest.txt";
 static double deadline,next;
 static int stage,index=-1,part;
 static StoryboardSteps board;
 static HybridTrainingController system;
 static HybridGuidedBindings bindings;
 static readonly List<string> result=new List<string>();
 static Quaternion rotorBefore;
 static HybridGuidedPlayTest(){ReportPath=SessionState.GetBool("RE009.TestFromLab",false)?"Temp/RE009Planning/guided-playtest-lab.txt":"Temp/RE009Planning/guided-playtest.txt";if(SessionState.GetBool("RE009.TestRequested",false)){deadline=EditorApplication.timeSinceStartup+240;next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}}
 [MenuItem("RE009/Test Full Guided Run From Main Menu")]
 public static void Begin(){
 if(Application.isPlaying)throw new Exception("Stop Play Mode first.");
 EditorSceneManager.SaveOpenScenes();EditorSceneManager.OpenScene("Assets/_Project/Scenes/Main Menu.unity");
 SessionState.SetBool("RE009.TestFromLab",false);File.WriteAllText(ReportPath,"RUNNING\n");SessionState.SetBool("RE009.TestRequested",true);EditorApplication.isPlaying=true;
 }
 [MenuItem("RE009/Test Full Guided Run From Lab Experiment Card")]
 public static void BeginLab(){if(Application.isPlaying)throw new Exception("Stop Play Mode first.");EditorSceneManager.SaveOpenScenes();EditorSceneManager.OpenScene("Assets/_Project/Scenes/Hybrid Lab.unity");SessionState.SetBool("RE009.TestFromLab",true);SessionState.SetBool("RE009.TestRequested",true);EditorApplication.isPlaying=true;}
 static void Check(bool condition,string text){if(!condition)throw new Exception(text);}
 static void Visible(Interaction point){
 var camera=HybridGuidedCompletion.All<SmoothCameraMovement>().Single().GetComponent<Camera>();var bounds=point.GetComponent<Collider>().bounds;var v=camera.WorldToViewportPoint(bounds.center);
 Check(v.z>0&&v.x>.015f&&v.x<.985f&&v.y>.015f&&v.y<.985f,"Camera does not frame "+point.name+" viewport="+v);
 var direction=bounds.center-camera.transform.position;
 if(Physics.Raycast(camera.transform.position,direction.normalized,out var hit,direction.magnitude+1f,~0,QueryTriggerInteraction.Collide))Check(hit.transform==point.transform||hit.transform.IsChildOf(point.transform),"Connector blocked: "+point.name+" by "+HybridGuidedCompletion.Path(hit.transform));
 else throw new Exception("No clickable ray hit for "+point.name);
 }
 static void Log(string value){Directory.CreateDirectory(System.IO.Path.GetDirectoryName(ReportPath));result.Add(value);File.WriteAllLines(ReportPath,result);}
 static void Finish(bool pass,string message){Log((pass?"PASS: ":"FAIL: ")+message);SessionState.SetBool("RE009.TestRequested",false);EditorApplication.update-=Tick;if(Application.isPlaying)Time.timeScale=1;Debug.Log("RE009 GUIDED TEST "+(pass?"PASS":"FAIL")+": "+message);}
 static void Tick(){
 if(!EditorApplication.isPlaying)return;
 if(EditorApplication.timeSinceStartup<next)return;
 try{
 if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Timed out at stage "+stage+" row "+index);
 if(stage==0){
  if(SessionState.GetBool("RE009.TestFromLab",false)){
   var start=HybridGuidedCompletion.All<Button>().FirstOrDefault(b=>b.name=="Start Underline Button"&&HybridGuidedCompletion.Path(b.transform).Contains(HybridGuidedCompletion.Display+"/"));if(!start)return;
   // The experiment card is normally shown by the Experiments panel toggle.
   for(var t=start.transform;t;t=t.parent)t.gameObject.SetActive(true);
   start.onClick.Invoke();stage=1;next=EditorApplication.timeSinceStartup+5;Log("Launched hybrid card from Hybrid Lab experiment menu.");return;
  }
  var launcher=HybridGuidedCompletion.All<MainMenuExperimentLauncher>().FirstOrDefault(l=>new SerializedObject(l).FindProperty("storyboardId").stringValue==HybridExperimentSetup.Id);
  if(!launcher)return;
  Check(launcher.gameObject.activeInHierarchy,"Hybrid main-menu card hidden");launcher.GetComponent<Button>().onClick.Invoke();stage=1;next=EditorApplication.timeSinceStartup+1;Log("Launched hybrid card from Main Menu.");return;
 }
 if(stage==1){
  if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!="Hybrid Lab")return;
  board=HybridGuidedCompletion.All<StoryboardSteps>().Single(b=>b.StoryboardID==HybridExperimentSetup.Id);
  if(!board.gameObject.activeInHierarchy||board.CurrentStep<0)return;
  Check(InteractionManager.Instance.ExperimentName==HybridGuidedCompletion.Display,"Wrong experiment title");
  system=board.GetComponentInChildren<HybridTrainingController>();bindings=board.GetComponent<HybridGuidedBindings>();Time.timeScale=4;stage=2;next=EditorApplication.timeSinceStartup+.4;Log("Hybrid Lab restored correct ID, title and guided storyboard.");return;
 }
 int current=board.CurrentStep;
 if(current!=index){index=current;part=0;next=EditorApplication.timeSinceStartup+.4;return;}
 var row=board.steps[index];
 if(index==board.steps.Count-1){
  Check(row.uiObject&&row.uiObject.activeInHierarchy,"Finished panel hidden");
  Check(system.lamps.All(l=>l.light.activeInHierarchy),"Connected AC lamps did not all light");
  Check(system.Reading.wind.rpm==1000,"Final RPM mismatch");
  Check(system.powerAnalyzerCanvas&&system.powerAnalyzerCanvas.activeInHierarchy&&system.powerAnalyzerText&&system.powerAnalyzerText.text.Contains("VAr"),"Wind Run did not enable the analyzer with the existing W/VAr/VA format.");
  Check(bindings.replacedVisuals.All(r=>r&&!r.enabled),"Stationary hardware meshes reappeared over guided control copies.");
  Check(bindings.powerOnIndicators.Length==0,"Unexpected added indicators; original layered button copies should own the glow.");
  Check(bindings.resetCovers.All(r=>r&&!r.enabled),"A completed power button still shows its unpressed cover.");
  foreach(var control in board.steps.Select(s=>s.interaction).OfType<SingleClickInteraction>())
   for(int call=0;call<control.onCompleted.GetPersistentEventCount();call++)
    if(control.onCompleted.GetPersistentMethodName(call)=="set_enabled"&&control.onCompleted.GetPersistentTarget(call) is Component visual)
     Check(visual.transform.IsChildOf(board.transform),"Button callback still changes an old experiment: "+control.name);
  Log("Power-button covers are hidden individually; visual callbacks stay within the hybrid experiment.");
  var graph=system.graph;var list=typeof(PVGraphController).GetField("plottedXValues",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(graph) as List<float>;
  Check(list!=null&&(system.recordGraphMeasurements?list.Count>0:list.Count==0),"Graph recording does not match the configured display behavior");
  Log("Finished panel reached. Four AC lamps on; rotor running; graph rows="+list.Count+"; source/battery readings live.");
  bindings.tabs.ShowGraph(bindings.graphButton);Check(bindings.graphPage.activeSelf&&!bindings.monitors.activeSelf,"Graph tab failed");bindings.tabs.ShowSystem();Check(!bindings.graphPage.activeSelf&&bindings.monitors.activeSelf,"System tab failed");Log("Graph/System tabs toggle correctly.");
  var csv=bindings.graphPage.GetComponent<PVExperimentExporter>().BuildWindCSV();Check(csv.StartsWith("Speed (RPM),DC voltage (V),DC current (A)\n"),"Export columns wrong");
  int final=index;system.windSpeed.SetSliderSpeed(800);system.windSpeed.SetSliderSpeed(1000);Check(board.CurrentStep==final,"Slider advanced twice after maximum step");
  graph.ClearRuntimeGraph();Check(list.Count==0,"Clear did not empty graph and rows");Log("CSV contains RPM/voltage/current; Clear works; later max-speed adjustments do not advance again.");
  Finish(true,"All "+board.steps.Count+" guided rows and 36 connections completed; camera framing and unobstructed raycasts passed for 72 wire endpoints, 10 controls and the Enable switch.");return;
 }
 if(row.stepType==StepType.Delay){if(part==0){Log("Displayed "+(row.notesObject?row.notesObject.name:row.uiObject?row.uiObject.name:"delay"));part=1;}next=EditorApplication.timeSinceStartup+.1;return;}
 if(row.interaction is WireInteraction wire){
  if(part==0){Check(wire.pointA.Allow&&!wire.pointB.Allow,"Wrong first endpoint gating at "+index);Check(wire.pointA.GetComponent<Collider>().enabled,"First banana collider disabled");Visible(wire.pointA);wire.pointB.Click();Check(!wire.wireObject.activeSelf,"Wrong endpoint connected a wire");wire.pointA.Click();Check(wire.pointB.Allow,"Second endpoint did not unlock");part=1;next=EditorApplication.timeSinceStartup+.4;return;}
  Check(wire.pointB.GetComponent<Collider>().enabled,"Second banana collider disabled");Visible(wire.pointB);wire.pointB.Click();Check(wire.wireObject.activeSelf&&wire.plugA.activeSelf&&wire.plugB.activeSelf,"Wire/plug state missing at "+index);Log("Connected "+wire.name);part=2;next=EditorApplication.timeSinceStartup+.3;return;
 }
 if(row.notesObject&&row.notesObject.GetComponent<MultipleChoiceQuiz>()){
  var quiz=row.notesObject.GetComponent<MultipleChoiceQuiz>();var q=quiz.questions[0];
  if(part==0){var wrong=q.answers.First(a=>!a.correct);wrong.button.onClick.Invoke();Check(wrong.incorrectHighlight.activeSelf&&q.answers.Where(a=>a!=wrong).All(a=>!a.incorrectHighlight.activeSelf&&!a.correctHighlight.activeSelf),"Quiz wrong highlights not independent");part=1;next=EditorApplication.timeSinceStartup+.5;return;}
  if(part==1){var correct=q.answers.First(a=>a.correct);correct.button.onClick.Invoke();Check(correct.correctHighlight.activeSelf,"Quiz correct highlight missing");part=2;next=EditorApplication.timeSinceStartup+.6;Log("Quiz wrong retry and correct-answer highlight passed.");return;}
 }
 if(row.interaction==bindings.speedWait){
  Check(bindings.speedCollider.enabled,"Speed collider did not unlock");
  if(part==0){Check(system.windSpeed.IsTurbineRunning,"Turbine not powered before speed step");rotorBefore=system.windSpeed.TurbineRotor.localRotation;part=1;next=EditorApplication.timeSinceStartup+.2;return;}
  Check(Quaternion.Angle(rotorBefore,system.windSpeed.TurbineRotor.localRotation)>.01f,"Turbine rotor is not turning");
  var checker=HybridGuidedCompletion.All<SliderRangeChecker>().Single(c=>new SerializedObject(c).FindProperty("windSpeedControllers").arraySize>0);var slider=new SerializedObject(checker).FindProperty("slider").objectReferenceValue as Slider;
  foreach(float rpm in new[]{200f,400f,600f,800f,1000f}){slider.value=rpm;Check(Mathf.Approximately(system.windSpeed.CurrentSpeed,rpm),"Slider speed did not reach "+rpm);system.Refresh();}
  Log("Slider stepped 200/400/600/800/1000 RPM and turbine rotation verified.");part=2;next=EditorApplication.timeSinceStartup+.4;return;
 }
 var enable=system.monitor.GetComponentInChildren<HybridEnableSwitch>(true);
 if(row.interaction==enable.instruction){
  var marker=enable.instruction.marker;Check(marker&&marker.activeInHierarchy,"Enable instruction arrow is missing or hidden");
  Check(marker.GetComponent<BopTarget>(),"Enable arrow does not use the existing bobbing behavior");
  Check(Vector3.Dot(marker.transform.parent.up,Vector3.up)>.9999f,"Enable arrow would bob sideways");
  Visible(enable.sound);enable.Click();Check(!marker.activeSelf,"Enable arrow remains visible after completion");
  Check(system.Reading.pvPower>0,"PV Enable switch did not enable source");Log("PV Enable bobbing arrow appears only for its instruction, bobs vertically, and hides on completion; PV output works.");next=EditorApplication.timeSinceStartup+.4;return;}
 if(row.interaction is SingleClickInteraction single&&single.interaction){
  Check(single.interaction.Allow&&single.interaction.GetComponent<Collider>().enabled,"Control not enabled: "+single.name);Visible(single.interaction);single.interaction.Click();
  if(single.name=="Main Board ON"){Check(system.MainPowered&&!system.blackScreen.activeSelf,"Main power/black-screen gating failed");Check(system.lamps.All(l=>l.light.activeInHierarchy),"Battery AC loads did not light after mains ON");}
  if(single.name=="Wind ON")Check(system.windSpeed.IsTurbineRunning,"Wind power did not start turbine");
  Log("Operated "+single.name);next=EditorApplication.timeSinceStartup+.4;return;
 }
 throw new Exception("Unhandled row "+index);
 }catch(Exception e){Finish(false,e.ToString());}
 }
}
